*{
    padding: 0;
    margin: 0;
    line-height: 1.5;
}
header{
    width: 100%;
    height: 80px;
    background-color: rgb(87, 119, 130);
}
h1{
    text-align: center;
    text-decoration: wavy;
    color: darkgrey;
    font-family: cursive;
    font-weight: bold;
    text-transform: capitalize;
}
main{
    width: 100%;
    height: 800px;
}
nav ul{
    padding-left: 10%;
    padding-top: 20%;
    list-style: none;
}
nav ul li{
   margin-bottom: 30px;
}
nav ul li a{
    text-decoration: none;
    font-weight: bold;
    font-size: larger;
    color: cadetblue;
}
section{
    width: 30%;
    float: left;
    height: 100%;
}
aside{
    padding-top: 3.5%;
    width: 70%;
    height: 80%;
    float: left;
}
iframe{
    width: 100%;
    height: 100%;
}

footer{
    width: 100%;
    height: 60px;
    background-color: rgb(87, 119, 130);
}

/*page ajout */

label{
    width: 20%;
    display: inline-block;
    margin-left: 3%;
}
input[type="text"]{
    width: 300px;
}
div{
    margin-bottom: 2%;
}
input[type="sumbit"],input[type="reset"]{
   margin-left: 40%;
}

